mapper.select:
SELECT id, user_id, resource_id, request_id, start_time, end_time, status,
       check_in_time, deleted, create_time, update_time
FROM resource_booking
WHERE resource_id = #{resourceId}
  AND start_time < #{endTime}
  AND end_time > #{startTime}
  AND status IN (0, 1)
  AND deleted = 0
